3	index 00000000..5b90bc28
4	--- /dev/null
5	+++ b/apps/obsidian/src/components/canvas/TextLinkDialog.tsx
6	@@ -0,0 +1,211 @@
7	+import { useCallback, useEffect, useRef, useState } from "react";
8	+import {
9	+  TLBaseShape,
10	+  TLShape,
11	+  TldrawUiButton,
12	+  TldrawUiButtonLabel,
13	+  TldrawUiDialogBody,
14	+  TldrawUiDialogCloseButton,
15	+  TldrawUiDialogFooter,
16	+  TldrawUiDialogHeader,
17	+  TldrawUiDialogTitle,
18	+  TldrawUiInput,
19	+  track,
20	+  useEditor,
21	+} from "tldraw";
22	+import {
23	+  getTextShapeLinkUrl,
24	+  isAllowedTextLinkUrl,
25	+} from "~/components/canvas/utils/textShapeLink";
26	+
27	+type ShapeWithUrl = TLBaseShape<string, { url: string }>;
28	+
29	+// Text shapes keep their link in `meta` so the stock props schema is untouched;
30	+// every other shape type uses tldraw's own `props.url`.
31	+const isTextShape = (shape: TLShape): boolean => shape.type === "text";
32	+
33	+const linkPatch = (shape: TLShape, url: string) =>
34	+  isTextShape(shape) ? { meta: { url } } : { props: { url } };
35	+
36	+const readLinkUrl = (shape: TLShape): string =>
37	+  isTextShape(shape)
38	+    ? getTextShapeLinkUrl(shape)
39	+    : (((shape.props as { url?: unknown }).url as string | undefined) ?? "");
40	+
41	+// Declared as a function property rather than reusing TLUiDialogProps, whose
42	+// method-shorthand onClose trips @typescript-eslint/unbound-method.
43	+type TextLinkDialogProps = { onClose: () => void };
44	+
45	+type UrlValidity = { isValid: boolean; hasProtocol: boolean };
46	+
47	+// Every shape type uses tldraw's linkUrl, patched to accept obsidian://open links.
48	+const validateUrl = (url: string): UrlValidity => {
49	+  if (isAllowedTextLinkUrl(url)) return { isValid: true, hasProtocol: true };
50	+  if (isAllowedTextLinkUrl(`https://${url}`))
51	+    return { isValid: true, hasProtocol: false };
52	+  return { isValid: false, hasProtocol: false };
53	+};
54	+
55	+// A fork of tldraw's EditLinkDialog, which is not exported. Copy differs: the
56	+// original's msg() keys are inlined, as this app has no i18n layer.
57	+export const TextLinkDialog = track(({ onClose }: TextLinkDialogProps) => {
58	+  const editor = useEditor();
59	+  const selectedShape = editor.getOnlySelectedShape();
60	+
61	+  const canEditLink =
62	+    selectedShape &&
63	+    (isTextShape(selectedShape) ||
64	+      ("url" in selectedShape.props &&
65	+        typeof selectedShape.props.url === "string"));
66	+
67	+  if (!canEditLink) return null;
68	+
69	+  return (
70	+    <TextLinkDialogInner
71	+      key={selectedShape.id}
72	+      onClose={onClose}
73	+      selectedShape={selectedShape as ShapeWithUrl}
74	+    />
75	+  );
76	+});
77	+
78	+const TextLinkDialogInner = track(
79	+  ({
80	+    onClose,
81	+    selectedShape,
82	+  }: TextLinkDialogProps & { selectedShape: ShapeWithUrl }) => {
83	+    const editor = useEditor();
84	+    const rInput = useRef<HTMLInputElement | null>(null);
85	+
86	+    useEffect(() => {
87	+      editor.timers.requestAnimationFrame(() => rInput.current?.focus());
88	+    }, [editor]);
89	+
90	+    const rInitialValue = useRef(readLinkUrl(selectedShape));
91	+
92	+    const [urlInputState, setUrlInputState] = useState(() => {
93	+      const initialUrl = readLinkUrl(selectedShape);
94	+      const result = validateUrl(initialUrl);
95	+      const initialValue = result.isValid
96	+        ? result.hasProtocol
97	+          ? initialUrl
98	+          : `https://${initialUrl}`
99	+        : "https://";
100	+      return { actual: initialValue, safe: initialValue, valid: true };
101	+    });
102	+
103	+    const handleChange = useCallback((rawValue: string) => {
104	+      // Auto-correct a doubled https:// from a bad paste.
105	+      const fixedRawValue = rawValue.replace(
106	+        /https?:\/\/(https?:\/\/)/,
107	+        (_match, arg1: string) => arg1,
108	+      );
109	+      const result = validateUrl(fixedRawValue);
110	+      const safeValue = result.isValid
111	+        ? result.hasProtocol
112	+          ? fixedRawValue
113	+          : `https://${fixedRawValue}`
114	+        : "https://";
115	+
116	+      setUrlInputState({
117	+        actual: fixedRawValue,
118	+        safe: safeValue,
119	+        valid: result.isValid,
120	+      });
121	+    }, []);
122	+
123	+    const handleClear = useCallback(() => {
124	+      const onlySelectedShape = editor.getOnlySelectedShape();
125	+      if (!onlySelectedShape) return;
126	+      editor.updateShapes([
127	+        {
128	+          id: onlySelectedShape.id,
129	+          type: onlySelectedShape.type,
130	+          ...linkPatch(onlySelectedShape, ""),
131	+        },
132	+      ]);
133	+      onClose();
134	+    }, [editor, onClose]);
135	+
136	+    const handleComplete = useCallback(() => {
137	+      // Enter reaches this even while Save is disabled, and the fallback
138	+      // "https://" fails both validators.
139	+      if (!urlInputState.valid) return;
140	+      const onlySelectedShape = editor.getOnlySelectedShape();
141	+      if (!onlySelectedShape) return;
142	+      if (readLinkUrl(onlySelectedShape) !== urlInputState.safe) {
143	+        editor.updateShapes([
144	+          {
145	+            id: onlySelectedShape.id,
146	+            type: onlySelectedShape.type,
147	+            ...linkPatch(onlySelectedShape, urlInputState.safe),
148	+          },
149	+        ]);
150	+      }
151	+      onClose();
152	+    }, [editor, onClose, urlInputState]);
153	+
154	+    const handleCancel = useCallback(() => {
155	+      onClose();
156	+    }, [onClose]);
157	+
158	+    const isRemoving = rInitialValue.current && !urlInputState.valid;
159	+
160	+    return (
161	+      <>
162	+        <TldrawUiDialogHeader>
163	+          <TldrawUiDialogTitle>Edit link</TldrawUiDialogTitle>
164	+          <TldrawUiDialogCloseButton />
165	+        </TldrawUiDialogHeader>
166	+        <TldrawUiDialogBody>
167	+          <div className="tlui-edit-link-dialog">
168	+            <TldrawUiInput
169	+              ref={rInput}
170	+              className="tlui-edit-link-dialog__input"
171	+              label="edit-link-dialog.url"
172	+              autoFocus
173	+              autoSelect
174	+              placeholder="https://example.com"
175	+              value={urlInputState.actual}
176	+              onValueChange={handleChange}
177	+              onComplete={handleComplete}
178	+              onCancel={handleCancel}
179	+            />
180	+            <div>
181	+              {!urlInputState.valid
182	+                ? "Invalid URL"
183	+                : "Enter a URL, or an obsidian:// link to a page."}
184	+            </div>
185	+          </div>
186	+        </TldrawUiDialogBody>
187	+        <TldrawUiDialogFooter className="tlui-dialog__footer__actions">
188	+          <TldrawUiButton
189	+            type="normal"
190	+            onClick={handleCancel}
191	+            onTouchEnd={handleCancel}
192	+          >
193	+            <TldrawUiButtonLabel>Cancel</TldrawUiButtonLabel>
194	+          </TldrawUiButton>
195	+          {isRemoving ? (
196	+            <TldrawUiButton
197	+              type="danger"
198	+              onClick={handleClear}
199	+              onTouchEnd={handleClear}
200	+            >
201	+              <TldrawUiButtonLabel>Clear</TldrawUiButtonLabel>
202	+            </TldrawUiButton>
203	+          ) : (
204	+            <TldrawUiButton
205	+              type="primary"
206	+              disabled={!urlInputState.valid}
207	+              onClick={handleComplete}
208	+              onTouchEnd={handleComplete}
209	+            >
210	+              <TldrawUiButtonLabel>Save</TldrawUiButtonLabel>
211	+            </TldrawUiButton>
212	+          )}
213	+        </TldrawUiDialogFooter>
214	+      </>
215	+    );
216	+  },
217	+);
