282	@@ -0,0 +1,59 @@
283	+import { HyperlinkButton, useEditor, useValue, TLShapeId } from "tldraw";
284	+import { getTextShapeLinkUrl } from "~/components/canvas/utils/textShapeLink";
285	+
286	+// Matches tldraw's own HyperlinkButton, which hides itself when zoomed out.
287	+const HIDE_BELOW_ZOOM = 0.32;
288	+
289	+type TextLink = { id: TLShapeId; url: string; left: number; top: number };
290	+
291	+// Rendered here, not on a custom shape util, so the stock text shape stays
292	+// untouched -- at the cost of rotation, frame clipping and stacking fidelity.
293	+export const TextLinkOverlay = () => {
294	+  const editor = useEditor();
295	+
296	+  const links = useValue<TextLink[]>(
297	+    "textShapeLinks",
298	+    () => {
299	+      if (editor.getZoomLevel() < HIDE_BELOW_ZOOM) return [];
300	+      const viewport = editor.getViewportPageBounds();
301	+      return editor.getCurrentPageShapes().flatMap<TextLink>((shape) => {
302	+        if (shape.type !== "text" || editor.isShapeHidden(shape)) return [];
303	+        const url = getTextShapeLinkUrl(shape);
304	+        if (!url) return [];
305	+        const bounds = editor.getShapePageBounds(shape.id);
306	+        if (!bounds || !viewport.includes(bounds)) return [];
307	+        const topRight = editor.pageToViewport({
308	+          x: bounds.maxX,
309	+          y: bounds.minY,
310	+        });
311	+        const bottomRight = editor.pageToViewport({
312	+          x: bounds.maxX,
313	+          y: bounds.maxY,
314	+        });
315	+        return [
316	+          {
317	+            id: shape.id,
318	+            url,
319	+            left: topRight.x,
320	+            top: (topRight.y + bottomRight.y) / 2,
321	+          },
322	+        ];
323	+      });
324	+    },
325	+    [editor],
326	+  );
327	+
328	+  return (
329	+    <div className="dg-text-link-overlay">
330	+      {links.map(({ id, url, left, top }) => (
331	+        <div
332	+          key={id}
333	+          className="dg-text-link-anchor"
334	+          style={{ left: `${left}px`, top: `${top}px` }}
335	+        >
336	+          <HyperlinkButton url={url} />
337	+        </div>
338	+      ))}
339	+    </div>
340	+  );
341	+};
