403	@@ -0,0 +1,66 @@
404	+import type { Editor } from "tldraw";
405	+import DiscourseGraphPlugin from "~/index";
406	+import {
407	+  parseObsidianOpenUrl,
408	+  resolveObsidianUrlToFile,
409	+} from "~/components/canvas/utils/externalContentHandlers";
410	+import {
411	+  openFileInNewLeaf,
412	+  openFileInNewTab,
413	+  openFileInSidebar,
414	+} from "~/components/canvas/utils/openFileUtils";
415	+import { showToast } from "~/components/canvas/utils/toastUtils";
416	+import { isObsidianUrl } from "~/components/canvas/utils/textShapeLink";
417	+
418	+type NavigateLinkDetail = {
419	+  url: string;
420	+  metaKey: boolean;
421	+  ctrlKey: boolean;
422	+  altKey: boolean;
423	+};
424	+
425	+// Patched tldraw dispatches this from every HyperlinkButton, so one listener
426	+// covers text-shape links and geo/note/image links alike.
427	+export const NAVIGATE_LINK_EVENT = "tldraw.navigate-link";
428	+
429	+export const registerLinkNavigation = (
430	+  editor: Editor,
431	+  plugin: DiscourseGraphPlugin,
432	+): (() => void) => {
433	+  const container = editor.getContainer();
434	+
435	+  const onNavigate = (event: Event) => {
436	+    const { url, metaKey, ctrlKey, altKey } = (
437	+      event as CustomEvent<NavigateLinkDetail>
438	+    ).detail;
439	+    if (!isObsidianUrl(url)) return;
440	+    // Cancelling tells tldraw to preventDefault, so the URI never reaches the
441	+    // OS handler and we keep the cross-vault check below.
442	+    event.preventDefault();
443	+
444	+    // The validator parses with `new URL`, so geo links may be stored as
445	+    // `Obsidian://…` or with leading spaces; the parser expects the normal form.
446	+    const parsed = parseObsidianOpenUrl(new URL(url).toString());
447	+    const file = parsed ? resolveObsidianUrlToFile(plugin, parsed) : null;
448	+    if (!file) {
449	+      showToast({
450	+        severity: "warning",
451	+        title: "Cannot open link",
452	+        description: "The linked file is not in this vault",
453	+      });
454	+      return;
455	+    }
456	+
457	+    // Mirrors the discourse-node gestures in TldrawViewComponent.
458	+    const open = altKey
459	+      ? openFileInNewLeaf
460	+      : metaKey || ctrlKey
461	+        ? openFileInNewTab
462	+        : openFileInSidebar;
463	+    void open(plugin.app, file);
464	+    editor.selectNone();
465	+  };
466	+
467	+  container.addEventListener(NAVIGATE_LINK_EVENT, onNavigate);
468	+  return () => container.removeEventListener(NAVIGATE_LINK_EVENT, onNavigate);
469	+};
470	diff --git a/apps/obsidian/src/components/canvas/utils/textShapeLink.ts b/apps/obsidian/src/components/canvas/utils/textShapeLink.ts
471	new file mode 100644
472	index 00000000..4c9159fd
473	--- /dev/null
474	+++ b/apps/obsidian/src/components/canvas/utils/textShapeLink.ts
475	@@ -0,0 +1,26 @@
476	+import { T, type TLShape } from "tldraw";
477	+
478	+// The patched tldraw validator is the single definition of a valid link, so geo
479	+// shapes and text shapes agree on what obsidian:// forms are accepted.
480	+export const isAllowedTextLinkUrl = (value: string): boolean =>
481	+  T.linkUrl.isValid(value);
482	+
483	+export const isObsidianUrl = (url: string): boolean => {
484	+  try {
485	+    return new URL(url).protocol.toLowerCase() === "obsidian:";
486	+  } catch {
487	+    return false;
488	+  }
489	+};
490	+
491	+// Returns the parsed form: `new URL` strips leading control characters, so a
492	+// raw value could pass the validator and fail a prefix test further on.
493	+export const getTextShapeLinkUrl = (shape: TLShape): string => {
494	+  const raw = (shape.meta as { url?: unknown }).url;
495	+  if (typeof raw !== "string" || !isAllowedTextLinkUrl(raw)) return "";
496	+  try {
497	+    return new URL(raw).toString();
498	+  } catch {
499	+    return "";
500	+  }
501	+};
